From cc58ca85f44d55e347b4c3158c5bead7c6d0c5d8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:41:20 +0100
Subject: [PATCH] faces: Update query sensors when sensors are added or removed

Sensor ids like "disk/.*/usedPercent" were only resolved once, so a disk
mounted after the widget loaded never showed up until Plasma restarted.
Resolve such queries again whenever the daemon adds or removes sensors.

BUG: 424578
---
 faces/SensorFaceController.cpp | 46 ++++++++++++++++++++++++++++++++++
 faces/SensorFaceController_p.h |  2 ++
 2 files changed, 48 insertions(+)

diff --git a/faces/SensorFaceController.cpp b/faces/SensorFaceController.cpp
index 89fbf8c4..5f4676a4 100644
--- a/faces/SensorFaceController.cpp
+++ b/faces/SensorFaceController.cpp
@@ -10,6 +10,7 @@
 #include <Sensor.h>
 #include <SensorQuery.h>

+#include <QDBusConnection>
 #include <QFileInfo>
 #include <QJsonDocument>
 #include <QQmlContext>
@@ -327,6 +328,33 @@ void SensorFaceControllerPrivate::resolveSensors(const QJsonArray &partialEntrie
     pendingResolvers.back()->execute();
 }

+void SensorFaceControllerPrivate::updateQueriedSensors(const QString &entryName, QJsonArray &sensors, void (SensorFaceController::*changedSignal)())
+{
+    static const QRegularExpression queryCharacters(QStringLiteral("[*+?|()\\[\\]{}^$\\\\]"));
+
+    const auto entries = QJsonDocument::fromJson(sensorsGroup.readEntry(entryName, QString()).toUtf8()).array();
+    const bool hasQuery = std::any_of(entries.begin(), entries.end(), [](const QJsonValue &entry) {
+        return entry.toString().contains(queryCharacters);
+    });
+    if (!hasQuery) {
+        return;
+    }
+
+    auto resolver = std::make_unique<SensorResolver>(q, entries);
+    resolver->callback = [this, &sensors, changedSignal](SensorResolver *resolver) {
+        if (resolver->found != sensors) {
+            sensors = resolver->found;
+            Q_EMIT(q->*changedSignal)();
+        }
+
+        std::erase_if(pendingResolvers, [resolver](const std::unique_ptr<SensorResolver> &candidate) {
+            return candidate.get() == resolver;
+        });
+    };
+    pendingResolvers.push_back(std::move(resolver));
+    pendingResolvers.back()->execute();
+}
+
 SensorFace *SensorFaceControllerPrivate::createGui(const QString &qmlPath)
 {
     QQmlComponent *component = new QQmlComponent(engine, qmlPath, nullptr);
@@ -426,6 +454,24 @@ SensorFaceController::SensorFaceController(KConfigGroup &config, QQmlEngine *eng
         Q_EMIT highPrioritySensorIdsChanged();
     });

+    // Sensors matching a query such as "disk/.*/usedPercent" can be added or removed at runtime, for example when a disk is mounted
+    d->sensorQueriesTimer = new QTimer(this);
+    d->sensorQueriesTimer->setSingleShot(true);
+    d->sensorQueriesTimer->setInterval(500);
+    connect(d->sensorQueriesTimer, &QTimer::timeout, this, [this]() {
+        d->updateQueriedSensors(QStringLiteral("totalSensors"), d->totalSensors, &SensorFaceController::totalSensorsChanged);
+        d->updateQueriedSensors(QStringLiteral("lowPrioritySensorIds"), d->lowPrioritySensorIds, &SensorFaceController::lowPrioritySensorIdsChanged);
+        d->updateQueriedSensors(QStringLiteral("highPrioritySensorIds"), d->highPrioritySensorIds, &SensorFaceController::highPrioritySensorIdsChanged);
+    });
+    for (const auto signal : {QStringLiteral("sensorAdded"), QStringLiteral("sensorRemoved")}) {
+        QDBusConnection::sessionBus().connect(QStringLiteral("org.kde.ksystemstats1"),
+                                              QStringLiteral("/org/kde/ksystemstats1"),
+                                              QStringLiteral("org.kde.ksystemstats1"),
+                                              signal,
+                                              d->sensorQueriesTimer,
+                                              SLOT(start()));
+    }
+
     setFaceId(d->appearanceGroup.readEntry("chartFace", QStringLiteral("org.kde.ksysguard.piechart")));
 }

diff --git a/faces/SensorFaceController_p.h b/faces/SensorFaceController_p.h
index 8e78fe07..cf682772 100644
--- a/faces/SensorFaceController_p.h
+++ b/faces/SensorFaceController_p.h
@@ -93,6 +93,7 @@ public:
     QString replaceDiskId(const QString &entryname) const;
     QString replacePartitionId(const QString &entryname) const;
     void resolveSensors(const QJsonArray &partialEntries, std::function<void(SensorResolver *)>);
+    void updateQueriedSensors(const QString &entryName, QJsonArray &sensors, void (SensorFaceController::*changedSignal)());
     SensorFace *createGui(const QString &qmlPath);
     QQuickItem *createConfigUi(const QString &file, const QVariantMap &initialProperties);

@@ -130,6 +131,7 @@ public:
     std::vector<std::unique_ptr<SensorResolver>> pendingResolvers;

     QTimer *syncTimer;
+    QTimer *sensorQueriesTimer = nullptr;
     bool shouldSync = true;
     FacesModel *availableFacesModel = nullptr;
     PresetsModel *availablePresetsModel = nullptr;
